test("statement annotations and references inside triple terms prevent hiding structural identity", () => {
  for (const reference of [
    { source: "urn:claim", subject: "cell0", statementPredicate: `${RDF}first`, object: "urn:a" },
    { source: "cell1", subject: "urn:a", statementPredicate: "urn:p", object: "urn:b" },
    { source: "urn:claim", subject: "cell1", statementPredicate: "urn:p", object: "urn:b" },
    { source: "urn:claim", subject: "urn:a", statementPredicate: "urn:p", object: "cell1" },
  ]) {
    const raw = list();
    raw.statementLinks = [{ id: "claim", predicate: "urn:mentions", label: "mentions",
      statementEdgeId: "not-a-transport-generated-id", ...reference }];
    assert.equal(analyzeCollections(raw).collections.get("cell0").collapsible, false);
    assert.equal(projectCollections(raw).hiddenCells.size, 0);
  }
  const onlyQuoted = { nodes: [blank("head"), iri("urn:a"), iri(`${RDF}nil`)], edges: [], revision: 1,
    statementLinks: [
      { id: "f", source: "urn:claim", predicate: "urn:mentions", label: "mentions", subject: "head",
        statementPredicate: `${RDF}first`, object: "urn:a", statementEdgeId: "f" },
      { id: "r", source: "urn:claim", predicate: "urn:mentions", label: "mentions", subject: "head",
        statementPredicate: `${RDF}rest`, object: `${RDF}nil`, statementEdgeId: "r" },
    ] };
  assert.equal(analyzeCollections(onlyQuoted).collections.has("head"), false);
});

test("duplicate statements are not branches, while distinct first/rest values are ambiguous", () => {
  const duplicated = list();
  duplicated.edges.push({ ...duplicated.edges[1], id: "duplicate-first" });
  duplicated.edges.push({ ...duplicated.edges[2], id: "duplicate-rest" });
  assert.equal(analyzeCollections(duplicated).collections.get("cell0").collapsible, true);
  assert.equal(projectCollections(duplicated).graph.edges.length, 1);
  for (const predicate of [`${RDF}first`, `${RDF}rest`]) {
    const raw = list();
    raw.edges.push(edge("cell1", predicate, "urn:other"));
    const info = analyzeCollections(raw).collections.get("cell0");
    assert.equal(info.status, "ambiguous");
    assert.equal(info.count, null);
    assert.equal(info.collapsible, false);
  }
  const branchingWithoutMember = list();
  branchingWithoutMember.edges = branchingWithoutMember.edges
    .filter((item) => item.source !== "cell1" || item.predicate !== `${RDF}first`);
  branchingWithoutMember.edges.push(edge("cell1", `${RDF}rest`, "urn:other"));
  assert.equal(analyzeCollections(branchingWithoutMember).collections.get("cell0").status, "ambiguous");
});

