  const cycle = list();
  cycle.edges = cycle.edges.map((item) => item.source === "cell2" && item.predicate === `${RDF}rest`
    ? edge("cell2", `${RDF}rest`, "cell0") : item);
  const analysis = analyzeCollections(cycle);
  assert.equal(analysis.collections.get("cell0").status, "cycle");
  assert.equal(analysis.collections.get("cell0").loadedCount, 3);
  assert.equal(collectionEntries(analysis, "cell0", 0, 100).length, 3);
  assert.equal(projectCollections(cycle).hiddenCells.size, 0);
  const literalTail = list();
