test("explicit connections reveal original first edges for expanded and shared lists with Values off", () => {
  for (const shared of [false, true]) {
    const raw = list([literal("v1", "one"), literal("v2", "two")]);
    raw.nodes.push(literal("note", "ordinary hidden value"));
    raw.edges.push(edge("urn:owner", "urn:note", "note"));
    if (shared) raw.edges.push(edge("urn:owner", "urn:tail", "cell1"));
    const projection = projectCollections(raw, analyzeCollections(raw), {
      expandedHeads: shared ? new Set() : new Set(["cell0"]), connectedHeads: new Set(["cell0"]),
    });
    assert.equal(projection.hiddenCells.size, 0);
    assert.ok(projection.graph.nodes.some((node) => node.id === "v1"));
    assert.ok(projection.graph.nodes.some((node) => node.id === "v2"));
    assert.equal(projection.graph.nodes.some((node) => node.id === "note"), false);
    assert.equal(projection.graph.edges.filter((item) => item.predicate === `${RDF}first`).length, 2);
    assert.equal(projection.graph.edges.some((item) => item.collection), false);
  }
});

test("a long list has bounded previews, iterative analysis, and stable suffix counts", () => {
  const raw = list(Array.from({ length: 20_000 }, (_, i) => iri(`urn:member:${i}`)));
  const analysis = analyzeCollections(raw);
  assert.equal(analysis.collections.get("cell0").count, 20_000);
  assert.equal(analysis.collections.get("cell19999").count, 1);
  assert.equal(analysis.cells.size, 20_000);
  const projection = projectCollections(raw, analysis);
  const card = projection.graph.nodes.find((node) => node.id === "cell0").collection;
  assert.equal(card.preview.length, 4);
  assert.equal(card.hiddenCount, 19_996);
  assert.equal(projection.hiddenCells.size, 19_999);
  const overlay = projectCollections(raw, analysis, { connectedHeads: new Set(["cell0"]) });
  assert.equal(overlay.graph.edges.filter(edge => edge.collection).length, 4);
  assert.equal(overlay.graph.nodes.length, 6);
});
